```  function isTodayHoliday(date) {
    var cal = CalendarApp.getCalendarById('ja.japanese#holiday@group.v.calendar.google.com');
    if (0 &lt; cal.getEventsForDay(date).length) {
      // "祝日カレンダー"の"今日"の予定にイベントがあるとき
      return true;
    }
    return false;
  }```
